package tech.hookin.challengor.ui

import androidx.lifecycle.ViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import tech.hookin.challengor.data.AppData
import tech.hookin.challengor.data.ChallengorRepository
import tech.hookin.challengor.model.User
import tech.hookin.challengor.model.isAdmin
import tech.hookin.challengor.navigation.Screen

data class AppUiState(
    val screen: Screen = Screen.HOME,
    val currentUser: User? = null,
    val data: AppData = AppData(),
)

class AppViewModel(
    private val repository: ChallengorRepository,
) : ViewModel() {

    private val _uiState = MutableStateFlow(snapshot(Screen.HOME))
    val uiState: StateFlow<AppUiState> = _uiState.asStateFlow()

    fun navigateTo(screen: Screen) = publish(screen)

    /** Admins land on the admin board, everyone else on their dashboard. */
    fun openDashboard() {
        publish(if (repository.currentUser?.isAdmin == true) Screen.ADMIN_BOARD else Screen.DASHBOARD)
    }

    /** Returns `false` if the credentials are wrong. */
    fun login(email: String, password: String): Boolean {
        repository.login(email, password) ?: return false
        openDashboard()
        return true
    }

    fun register(name: String, email: String, password: String) {
        repository.register(name, email, password) ?: return
        openDashboard()
    }

    fun logout() {
        repository.logout()
        publish(Screen.HOME)
    }

    fun createChallenge(name: String, description: String, typesInput: String) {
        val user = repository.currentUser ?: return
        repository.createChallenge(user.id, name, description, typesInput)
        publish(_uiState.value.screen)
    }

    private fun publish(screen: Screen) {
        _uiState.value = snapshot(screen)
    }

    private fun snapshot(screen: Screen) = AppUiState(
        screen = screen,
        currentUser = repository.currentUser,
        data = repository.data,
    )
}
