package tech.hookin.challengor.ui.screens

import androidx.compose.foundation.border
import androidx.compose.foundation.horizontalScroll
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.IntrinsicSize
import androidx.compose.foundation.layout.Row
import androidx.compose.foundation.layout.defaultMinSize
import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.layout.width
import androidx.compose.foundation.rememberScrollState
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.style.TextAlign
import androidx.compose.ui.unit.dp
import tech.hookin.challengor.data.AppData
import tech.hookin.challengor.model.User
import tech.hookin.challengor.ui.components.BoardTopBar
import tech.hookin.challengor.ui.components.H2
import tech.hookin.challengor.ui.components.MainPage

@Composable
fun AdminBoardScreen(
    user: User,
    data: AppData,
    onBack: () -> Unit,
    onLogout: () -> Unit,
    onOpenUserDashboard: () -> Unit,
) {
    MainPage {
        BoardTopBar(
            onBack = onBack,
            onLogout = onLogout,
            actionLabel = "User Board",
            onAction = onOpenUserDashboard,
        )
        H2("Welcome ${user.name}")
        Text(user.email, textAlign = TextAlign.Center, maxLines = 1)
        Text("ID: ${user.id}", textAlign = TextAlign.Center)

        H2("All registered users")
        UsersTable(data)
    }
}

@Composable
private fun UsersTable(data: AppData) {
    val users = data.users
    val columns = listOf(
        "ID" to users.map { it.id.toString() },
        "Name" to users.map { it.name },
        "Email" to users.map { it.email },
        "Registered on" to users.map { it.registeredOn },
        "Created challenges" to users.map { user ->
            data.challengesOf(user).joinToString(", ") { it.name }.ifEmpty { "No challenges created" }
        },
        "Challenge types" to users.map { user ->
            data.typeNamesOf(user).joinToString(", ").ifEmpty { "No challenge types" }
        },
    )

    Box(
        modifier = Modifier
            .fillMaxWidth()
            .horizontalScroll(rememberScrollState()),
        contentAlignment = Alignment.Center,
    ) {
        Row(modifier = Modifier.border(TableBorderWidth, MaterialTheme.colorScheme.outline)) {
            columns.forEach { (header, values) -> TableColumn(header, values) }
        }
    }
}

private val TableBorderWidth = 1.dp

@Composable
private fun TableColumn(header: String, values: List<String>) {
    Column(
        modifier = Modifier.width(IntrinsicSize.Max),
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        TableCell(header, isHeader = true)
        values.forEach { TableCell(it) }
    }
}

@Composable
private fun TableCell(value: String, isHeader: Boolean = false) {
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .border(TableBorderWidth, MaterialTheme.colorScheme.outline.copy(alpha = 0.5f))
            .defaultMinSize(minHeight = 40.dp)
            .padding(8.dp),
        contentAlignment = Alignment.Center,
    ) {
        Text(
            text = value,
            textAlign = TextAlign.Center,
            fontWeight = if (isHeader) FontWeight.Bold else null,
            maxLines = 1,
        )
    }
}
