package tech.hookin.challengor.ui.components

import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Row
import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.material3.Icon
import androidx.compose.material3.IconButton
import androidx.compose.runtime.Composable
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import com.adamglin.PhosphorIcons
import com.adamglin.phosphoricons.Regular
import com.adamglin.phosphoricons.regular.ArrowLeft
import com.adamglin.phosphoricons.regular.SignOut

/** Back, optional centre action and logout – shared by the dashboard and the admin board. */
@Composable
fun BoardTopBar(
    onBack: () -> Unit,
    onLogout: () -> Unit,
    actionLabel: String? = null,
    onAction: () -> Unit = {},
) {
    Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically,
    ) {
        IconButton(onClick = onBack) {
            Icon(PhosphorIcons.Regular.ArrowLeft, contentDescription = "Back")
        }
        if (actionLabel != null) {
            MainButton(text = actionLabel, onClick = onAction)
        }
        IconButton(onClick = onLogout) {
            Icon(PhosphorIcons.Regular.SignOut, contentDescription = "Log out")
        }
    }
}
