package tech.hookin.challengor.data

import com.russhwolf.settings.Settings
import kotlinx.datetime.TimeZone
import kotlinx.datetime.toLocalDateTime
import tech.hookin.challengor.domain.parseTypeNames
import tech.hookin.challengor.model.Challenge
import tech.hookin.challengor.model.ChallengeType
import tech.hookin.challengor.model.ChallengeTypeRef
import tech.hookin.challengor.model.User
import kotlin.time.Clock
import kotlin.time.ExperimentalTime

/**
 * Single source of truth for users, challenges and their types.
 * Every mutation is persisted immediately.
 */
class ChallengorRepository(
    settings: Settings,
    private val passwordHasher: PasswordHasher = PasswordHasher(),
    private val timestamp: () -> String = ::currentTimestamp,
) {
    private val store = JsonSettingsStore(settings)

    var data: AppData = AppData(
        users = store.load(KEY_USERS) ?: emptyList(),
        challenges = store.load(KEY_CHALLENGES) ?: emptyList(),
        challengeTypes = store.load(KEY_CHALLENGE_TYPES) ?: emptyList(),
        challengeTypeRefs = store.load(KEY_CHALLENGE_TYPE_REFS) ?: emptyList(),
    )
        private set

    var currentUser: User? = store.load<User>(KEY_CURRENT_USER)
        ?.let { saved -> data.users.find { it.id == saved.id } }
        private set

    /** Creates an account and logs it in. Returns `null` if the name or email is already taken. */
    fun register(name: String, email: String, password: String): User? {
        val trimmedName = name.trim()
        val trimmedEmail = email.trim()
        if (trimmedName.isEmpty() || data.isNameTaken(trimmedName) || data.isEmailTaken(trimmedEmail)) {
            return null
        }
        val salt = passwordHasher.newSalt()
        val user = User(
            id = nextId(data.users) { it.id },
            name = trimmedName,
            email = trimmedEmail,
            registeredOn = timestamp(),
            passwordHash = passwordHasher.hash(password, salt),
            salt = salt,
        )
        updateData(data.copy(users = data.users + user))
        updateCurrentUser(user)
        return user
    }

    /**
     * Logs in with email and password. Accounts created by older versions (plain-text
     * password) are migrated to a salted hash on their first successful login.
     */
    fun login(email: String, password: String): User? {
        val user = data.users.find { it.email.equals(email.trim(), ignoreCase = true) } ?: return null
        val loggedIn = when {
            user.passwordHash.isNotEmpty() ->
                user.takeIf { passwordHasher.verify(password, it.salt, it.passwordHash) }

            user.password == password -> migratePassword(user, password)
            else -> null
        } ?: return null

        updateCurrentUser(loggedIn)
        return loggedIn
    }

    fun logout() = updateCurrentUser(null)

    /**
     * Creates a challenge for [userId]. [typesInput] is a comma-separated list of type
     * names. Missing types are created; matching is case-insensitive.
     */
    fun createChallenge(userId: Int, name: String, description: String, typesInput: String): Challenge? {
        val user = data.users.find { it.id == userId } ?: return null
        val typeNames = parseTypeNames(typesInput)
        if (name.isBlank() || typeNames.isEmpty()) return null

        val challenge = Challenge(
            id = nextId(data.challenges) { it.id },
            name = name.trim(),
            description = description.trim(),
        )
        val newTypes = typeNames
            .filter { typeName -> data.challengeTypes.none { it.name == typeName } }
            .map(::ChallengeType)
        val newRefs = typeNames.map { ChallengeTypeRef(challengeId = challenge.id, typeName = it) }
        val updatedUser = user.copy(createdChallengeIds = user.createdChallengeIds + challenge.id)

        updateData(
            data.copy(
                users = data.users.replacing(updatedUser),
                challenges = data.challenges + challenge,
                challengeTypes = data.challengeTypes + newTypes,
                challengeTypeRefs = data.challengeTypeRefs + newRefs,
            )
        )
        if (currentUser?.id == userId) updateCurrentUser(updatedUser)
        return challenge
    }

    private fun migratePassword(user: User, password: String): User {
        val salt = passwordHasher.newSalt()
        val migrated = user.copy(
            passwordHash = passwordHasher.hash(password, salt),
            salt = salt,
            password = null,
        )
        updateData(data.copy(users = data.users.replacing(migrated)))
        return migrated
    }

    private fun updateData(newData: AppData) {
        data = newData
        store.save(KEY_USERS, newData.users)
        store.save(KEY_CHALLENGES, newData.challenges)
        store.save(KEY_CHALLENGE_TYPES, newData.challengeTypes)
        store.save(KEY_CHALLENGE_TYPE_REFS, newData.challengeTypeRefs)
    }

    private fun updateCurrentUser(user: User?) {
        currentUser = user
        store.save(KEY_CURRENT_USER, user)
    }

    private fun List<User>.replacing(user: User): List<User> =
        map { if (it.id == user.id) user else it }

    private companion object {
        // Keys are unchanged from earlier versions so existing data keeps loading.
        const val KEY_USERS = "users"
        const val KEY_CURRENT_USER = "current_user"
        const val KEY_CHALLENGES = "challenges"
        const val KEY_CHALLENGE_TYPES = "challenge_types"
        const val KEY_CHALLENGE_TYPE_REFS = "challenge_type_refs"
    }
}

@OptIn(ExperimentalTime::class)
private fun currentTimestamp(): String =
    Clock.System.now().toLocalDateTime(TimeZone.currentSystemDefault()).toString()
