package tech.hookin.challengor.model

import kotlinx.serialization.Serializable

@Serializable
data class User(
    val id: Int,
    val name: String,
    val email: String,
    val registeredOn: String,
    val createdChallengeIds: List<Int> = emptyList(),
    val passwordHash: String = "",
    val salt: String = "",
    /** Plain-text password written by older app versions. Only read for migration, never written. */
    val password: String? = null,
)

private val ADMIN_EMAILS = setOf(
    "annahook@gmx.de",
    "annahook0@gmail.com",
)

val User.isAdmin: Boolean
    get() = email.lowercase() in ADMIN_EMAILS
