package tech.hookin.challengor

import androidx.compose.runtime.Composable
import androidx.compose.runtime.getValue
import androidx.lifecycle.compose.collectAsStateWithLifecycle
import androidx.lifecycle.viewmodel.compose.viewModel
import tech.hookin.challengor.data.ChallengorRepository
import tech.hookin.challengor.data.provideSettings
import tech.hookin.challengor.model.isAdmin
import tech.hookin.challengor.navigation.Screen
import tech.hookin.challengor.ui.AppViewModel
import tech.hookin.challengor.ui.components.AuthGuard
import tech.hookin.challengor.ui.screens.AdminBoardScreen
import tech.hookin.challengor.ui.screens.DashboardScreen
import tech.hookin.challengor.ui.screens.LandingScreen
import tech.hookin.challengor.ui.screens.LoginScreen
import tech.hookin.challengor.ui.screens.RegisterScreen
import tech.hookin.challengor.ui.theme.ChallengorTheme

@Composable
fun App(
    viewModel: AppViewModel = viewModel { AppViewModel(ChallengorRepository(provideSettings())) },
) {
    val state by viewModel.uiState.collectAsStateWithLifecycle()
    val goHome = { viewModel.navigateTo(Screen.HOME) }

    ChallengorTheme {
        when (state.screen) {
            Screen.HOME -> LandingScreen(
                isLoggedIn = state.currentUser != null,
                onLogin = { viewModel.navigateTo(Screen.LOGIN) },
                onRegister = { viewModel.navigateTo(Screen.REGISTER) },
                onOpenDashboard = viewModel::openDashboard,
            )

            Screen.LOGIN -> LoginScreen(
                onBack = goHome,
                onLogin = viewModel::login,
            )

            Screen.REGISTER -> RegisterScreen(
                onBack = goHome,
                isNameTaken = state.data::isNameTaken,
                isEmailTaken = state.data::isEmailTaken,
                onRegister = viewModel::register,
                onGoToLogin = { viewModel.navigateTo(Screen.LOGIN) },
            )

            Screen.DASHBOARD -> AuthGuard(state.currentUser, onRequireLogin = goHome) { user ->
                DashboardScreen(
                    user = user,
                    challenges = state.data.challengesOf(user),
                    onBack = goHome,
                    onLogout = viewModel::logout,
                    onOpenAdminBoard = if (user.isAdmin) {
                        { viewModel.navigateTo(Screen.ADMIN_BOARD) }
                    } else {
                        null
                    },
                    onCreateChallenge = viewModel::createChallenge,
                )
            }

            Screen.ADMIN_BOARD -> AuthGuard(state.currentUser, onRequireLogin = goHome) { user ->
                AdminBoardScreen(
                    user = user,
                    data = state.data,
                    onBack = goHome,
                    onLogout = viewModel::logout,
                    onOpenUserDashboard = { viewModel.navigateTo(Screen.DASHBOARD) },
                )
            }
        }
    }
}
