package tech.hookin.challengor.data

import tech.hookin.challengor.model.Challenge
import tech.hookin.challengor.model.ChallengeType
import tech.hookin.challengor.model.ChallengeTypeRef
import tech.hookin.challengor.model.User

/** Snapshot of everything the app persists. */
data class AppData(
    val users: List<User> = emptyList(),
    val challenges: List<Challenge> = emptyList(),
    val challengeTypes: List<ChallengeType> = emptyList(),
    val challengeTypeRefs: List<ChallengeTypeRef> = emptyList(),
) {
    fun isNameTaken(name: String): Boolean =
        users.any { it.name.equals(name.trim(), ignoreCase = true) }

    fun isEmailTaken(email: String): Boolean =
        users.any { it.email.equals(email.trim(), ignoreCase = true) }

    fun challengesOf(user: User): List<Challenge> =
        challenges.filter { it.id in user.createdChallengeIds }

    fun typeNamesOf(user: User): List<String> =
        challengeTypeRefs
            .filter { it.challengeId in user.createdChallengeIds }
            .map { it.typeName }
            .distinct()
}
