package tech.hookin.challengor.ui.components

import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import tech.hookin.challengor.model.User

/** Shows [content] for a logged-in [user], otherwise a hint with a way back. */
@Composable
fun AuthGuard(
    user: User?,
    onRequireLogin: () -> Unit,
    content: @Composable (User) -> Unit,
) {
    if (user != null) {
        content(user)
        return
    }
    MainPage {
        Text("Log in to see this page.")
        MainButton(text = "Go to start page", onClick = onRequireLogin)
    }
}
